import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private static final Map<String, String> TEMPLATE_QUERIES = new HashMap<>();
    static {
        TEMPLATE_QUERIES.put("sales", "SELECT * FROM sales WHERE region = '${region}' AND quarter = '${quarter}'");
        TEMPLATE_QUERIES.put("inventory", "SELECT * FROM inventory WHERE warehouse = '${warehouse}' AND status = '${status}'");
        TEMPLATE_QUERIES.put("employees", "SELECT * FROM employees WHERE department = '${dept}' AND role = '${role}'");
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String reportType = request.getParameter("type");
        if (reportType == null || !TEMPLATE_QUERIES.containsKey(reportType)) {
            response.sendError(400, "Invalid report type");
            return;
        }

        // Collect user-supplied parameters for template substitution
        Map<String, String> params = new HashMap<>();
        Enumeration<String> paramNames = request.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String name = paramNames.nextElement();
            if (!name.equals("type")) {
                params.put(name, request.getParameter(name));
            }
        }

        // Build query from template using Apache Commons Text StringSubstitutor
        String templateQuery = TEMPLATE_QUERIES.get(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        sub.setEnableUndefinedVariableException(false);
        String finalQuery = sub.replace(templateQuery);

        // Log for audit
        getServletContext().log("Executing report query: " + finalQuery);

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;
        try {
            conn = getConnection();
            stmt = conn.createStatement();
            rs = stmt.executeQuery(finalQuery);

            response.setContentType("application/json");
            PrintWriter out = response.getWriter();
            out.write(resultSetToJson(rs));
        } catch (SQLException e) {
            response.sendError(500, "Query execution failed");
        } finally {
            if (rs != null) try { rs.close(); } catch (SQLException e) {}
            if (stmt != null) try { stmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
